insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g2_pe_v1'
from (values
('116.14.b.1.A',2,'Which locomotor skill has you move with an uneven step-step-hop pattern, like a quick rhythm on each side?','["skipping", "standing", "kneeling", "sitting"]'::jsonb,0,'Skipping alternates steps and hops.','original'),
('116.14.b.1.A',3,'When running for speed, your arms should bend and swing...','["side to side only", "forward and backward", "not at all", "in circles"]'::jsonb,1,'Arms drive the body forward.','original'),
('116.14.b.1.A',3,'A gallop is different from a skip because a gallop...','["uses hands", "uses no feet", "keeps the same foot in front", "alternates feet"]'::jsonb,2,'In a gallop, one foot leads the whole time.','original'),
('116.14.b.1.B',3,'A correct landing from a jump is on the balls of your feet with your knees...','["locked", "crossed", "turned out", "bent"]'::jsonb,3,'Bent knees cushion the impact.','original'),
('116.14.b.1.B',3,'Jumping consecutively backward means you...','["jump again and again toward your back", "stand still", "jump once", "spin in place"]'::jsonb,0,'Consecutive jumps repeat.','original'),
('116.14.b.1.C',3,'Cross lateralization means using...','["one arm only", "opposite sides of the body together", "no limbs", "one leg only"]'::jsonb,1,'Opposite arm and leg work together.','original'),
('116.14.b.1.C',3,'Which pair is an example of cross lateral movement?','["both hands clapping", "a head nod", "right hand touching left knee", "both feet jumping"]'::jsonb,2,'Crossing the midline uses both sides.','original'),
('116.14.b.1.D',2,'A forward roll is done by tucking your chin and rolling over your...','["knees only", "stomach", "face", "rounded back"]'::jsonb,3,'A tucked, curved back protects the neck.','original'),
('116.14.b.1.D',3,'Spinning at a high level means you spin while...','["standing tall or on your toes", "sitting", "lying down", "crawling"]'::jsonb,0,'High level is up high.','original'),
('116.14.b.2.A',2,'Standing on one foot for eight seconds without wobbling mostly tests your...','["hearing", "ability to stay steady", "eyesight", "running speed"]'::jsonb,1,'Balance holds a steady body position.','original'),
('116.14.b.2.A',3,'Keeping your eyes on a spot that does not move helps your...','["hearing", "temperature", "balance", "hair"]'::jsonb,2,'A focal point steadies balance.','original'),
('116.14.b.2.B',3,'Which action means to move toward your body with force?','["twist", "push", "sway", "pull"]'::jsonb,3,'Pulling draws something toward you.','original'),
('116.14.b.2.B',3,'Pushing is when you...','["move something away from your body", "turn it", "bring it closer", "stay still"]'::jsonb,0,'Pushing moves away.','original'),
('116.14.b.3.A',3,'When throwing overhand, which arm moves toward the target?','["your head", "your throwing arm after the opposite foot steps", "both feet", "your non-throwing arm only"]'::jsonb,1,'Step with the opposite foot, then throw.','original'),
('116.14.b.3.A',3,'A partner underhand throw should be tossed...','["at the face", "up high out of reach", "gently so the partner can catch it", "as hard as possible"]'::jsonb,2,'Throw softly to a partner.','original'),
('116.14.b.3.B',3,'Catching without trapping the ball against your body means you catch with your...','["chin", "chest", "elbows", "hands and fingers"]'::jsonb,3,'Use hands to catch, not the body.','original'),
('116.14.b.3.C',3,'When dribbling with a hand while walking, you push the ball...','["out in front and a little to the side", "down your shirt", "high above your head", "straight behind you"]'::jsonb,0,'Dribble in front, near your side.','original'),
('116.14.b.3.D',3,'Dribbling with both feet means you tap the ball with your...','["elbows", "right foot and left foot", "knees", "hands"]'::jsonb,1,'Use both feet for control.','original'),
('116.14.b.3.E',3,'To kick a rolling ball, you run toward it and...','["catch it", "stand and hope", "swing your leg to meet it", "sit"]'::jsonb,2,'A running approach lines up the kick.','original'),
('116.14.b.3.F',3,'Volleying consecutively means hitting a light object...','["never", "once only", "only to the floor", "again and again without it touching the ground"]'::jsonb,3,'Consecutive means in a row.','original'),
('116.14.b.3.G',3,'To strike a stationary object off a tee, you should...','["swing smoothly through the ball", "stop before it", "close your eyes", "let go of the bat early"]'::jsonb,0,'A level, smooth swing makes contact.','original'),
('116.14.b.3.H',2,'Jumping forward and backward over a self-turned rope means you...','["skip rope with someone", "turn the rope the same way and jump over it each time", "let the rope go slack", "drop it"]'::jsonb,1,'Rope jumping needs rhythm.','original'),
('116.14.b.3.I',3,'When a long rope is turned, a jumper should enter...','["when the rope is tangled", "before the rope starts", "at the right time as the rope comes toward them", "never"]'::jsonb,2,'Timing helps the jumper enter.','original'),
('116.14.b.4.A',2,'A skill that moves you from place to place is called...','["a non-locomotor skill", "a manipulative skill", "a rest", "a locomotor skill"]'::jsonb,3,'Locomotor skills travel.','original'),
('116.14.b.4.A',3,'A skill that is done without traveling, like bending, is...','["non-locomotor", "manipulative", "vigorous", "locomotor"]'::jsonb,0,'Non-locomotor skills stay in place.','original'),
('116.14.b.4.A',3,'Throwing and catching a ball are examples of...','["rest skills", "manipulative skills", "non-locomotor skills", "locomotor skills"]'::jsonb,1,'Manipulatives use objects.','original'),
('116.14.b.4.B',3,'A simple sequence could be...','["a shout", "one jump", "a low roll, a curved pathway, and a stretch", "a nap"]'::jsonb,2,'A sequence has more than one movement.','original'),
('116.14.b.4.C',3,'Combining speed and direction could mean...','["sitting", "singing", "standing still", "moving fast forward then slow sideways"]'::jsonb,3,'Speed and direction combine in a sequence.','original'),
('116.14.b.5',3,'A short dance pattern repeated to the music uses...','["rhythm and movement", "only color", "only sound", "only speed"]'::jsonb,0,'Dance moves follow the rhythm.','original'),
('116.14.b.5',3,'Moving in time with the beats of a song shows good...','["cold", "rhythm", "weight", "height"]'::jsonb,1,'Rhythm matches the beat.','original'),
('116.14.b.6.A',3,'Dodging at a low level means you...','["sit", "fly", "duck down to avoid a tag", "stand tall"]'::jsonb,2,'Levels change how you dodge.','original'),
('116.14.b.6.A',3,'Which game uses chasing, fleeing, and dodging?','["a spelling test", "a jump rope contest", "a puzzle", "a tag game"]'::jsonb,3,'Tag uses all three.','original'),
('116.14.b.6.B',3,'A drill is a practice activity used to...','["improve a specific skill", "skip class", "rest", "win a prize"]'::jsonb,0,'Drills build skills.','original'),
('116.14.b.6.C',3,'Using equipment safely means you...','["throw it at others", "check it and use it the right way", "bend it", "hide it"]'::jsonb,1,'Safe use prevents injury.','original'),
('116.14.b.7',3,'Outdoor and recreational activities you can do with a bike include...','["baking", "watching TV", "riding on a trail", "sleeping"]'::jsonb,2,'Biking is recreation.','original'),
('116.14.b.7',3,'A safe way to hike is to...','["run off alone", "drink from a puddle", "leave the group", "stay on the trail and bring water"]'::jsonb,3,'Hiking safely means planning.','original'),
('116.14.b.8.A',3,'One benefit of regular exercise on your heart is that it...','["gets stronger", "gets weaker", "turns off", "stops"]'::jsonb,0,'Regular activity strengthens the heart.','original'),
('116.14.b.8.A',3,'One benefit of exercise on your lungs is that you can...','["breathe less", "take in more air", "lose them", "stop breathing"]'::jsonb,1,'Lungs work better with exercise.','original'),
('116.14.b.8.B',3,'Frequency in exercise means...','["how tall you are", "how heavy you are", "how often you exercise", "what color you wear"]'::jsonb,2,'Frequency is how many times.','original'),
('116.14.b.8.B',3,'Endurance in exercise means...','["how loud you are", "how big you are", "how fast you can run once", "how long you can keep going"]'::jsonb,3,'Endurance is lasting power.','original'),
('116.14.b.8.C',3,'A correct push-up keeps your body in a...','["straight line", "curve", "slump", "hunch"]'::jsonb,0,'Straight alignment protects your back.','original'),
('116.14.b.9.A',3,'A skill-related goal could be to...','["ignore feedback", "jump rope 20 times in a row", "skip class", "never practice"]'::jsonb,1,'Skill goals improve a skill.','original'),
('116.14.b.9.B',3,'To track progress in a standing jump, you could use a...','["pillow", "balloon", "tape measure and a chart", "spoon"]'::jsonb,2,'Charts track changes.','original'),
('116.14.b.10.A',3,'Which type of food gives your body lasting energy?','["frosting", "soda", "candy", "whole grains and fruits"]'::jsonb,3,'Whole foods supply steady energy.','original'),
('116.14.b.10.B',3,'Why is it important to drink water before, during, and after activity?','["it replaces fluid you lose by sweating", "it makes you tired", "it makes you thirsty", "it stops sweating"]'::jsonb,0,'Water replaces sweat.','original'),
('116.14.b.11.A',3,'How does a helmet keep you safe?','["it keeps you cold", "it protects your head from injury", "it makes you heavy", "it makes you faster"]'::jsonb,1,'Helmets cushion head impacts.','original'),
('116.14.b.11.A',3,'Shin guards are used in soccer to protect your...','["ears", "hands", "lower legs", "eyes"]'::jsonb,2,'Shin guards cover shins.','original'),
('116.14.b.11.B',3,'Skating safety includes wearing...','["a scarf", "nothing", "flip flops", "a helmet, wrist guards, and pads"]'::jsonb,3,'Pads protect joints.','original'),
('116.14.b.11.B',3,'Pedestrian safety means you should cross...','["at a crosswalk when the signal says go", "between parked cars", "anywhere you want", "without looking"]'::jsonb,0,'Crosswalks are safer.','original'),
('116.14.b.12.A',3,'A positive consequence of telling the truth is that people...','["forget you", "trust you", "get angry", "laugh"]'::jsonb,1,'Honesty builds trust.','original'),
('116.14.b.12.A',3,'A negative consequence of not sharing equipment is that...','["everyone is happy", "teams win", "others may feel left out", "games go faster"]'::jsonb,2,'Not sharing hurts feelings.','original'),
('116.14.b.12.B',3,'Showing respect for different abilities means you...','["laugh at them", "ignore them", "complain", "help and cheer for others"]'::jsonb,3,'Respect includes support.','original'),
('116.14.b.12.C',3,'Which is a self-management skill to calm yourself?','["taking a deep breath", "throwing things", "kicking others", "yelling"]'::jsonb,0,'Deep breaths help control impulses.','original'),
('116.14.b.13.A',3,'If two friends want the same ball, a good solution is to...','["fight over it", "take turns", "run away", "break it"]'::jsonb,1,'Taking turns solves the problem.','original'),
('116.14.b.13.A',3,'The cause of a problem is...','["how it ends", "the color of it", "what made it happen", "its size"]'::jsonb,2,'Cause explains why.','original'),
('116.14.b.13.B',3,'Communicating feelings without being reminded means you...','["wait for someone to guess", "shout", "hide your feelings", "say how you feel on your own"]'::jsonb,3,'You can use words by yourself.','original'),
('116.14.b.14',3,'When a skill is hard, perseverance helps you to...','["try again with a good attitude", "blame others", "quit", "hide"]'::jsonb,0,'Perseverance is continued effort.','original'),
('116.14.b.14',3,'Which is an example of perseverance?','["giving up", "practicing a jump rope skill every day until you improve", "quitting after one try", "ignoring the teacher"]'::jsonb,1,'Daily practice shows grit.','original'),
('116.14.b.15',3,'When someone says, "Try bending your knees more," that is...','["a joke", "a rule", "helpful feedback", "a mean comment"]'::jsonb,2,'Feedback gives a tip for improvement.','original'),
('116.14.b.15',3,'After getting feedback, a good response is to...','["blame others", "get upset", "walk away", "thank them and try it"]'::jsonb,3,'Accepting feedback helps growth.','original'),
('116.14.b.16.A',3,'Moderate to vigorous activity should happen...','["on a regular basis", "once a year", "never", "only on holidays"]'::jsonb,0,'Regular activity builds health.','original'),
('116.14.b.16.B',3,'You should choose activities you enjoy because...','["they cost less", "you are more likely to keep doing them", "they are lazier", "they are easier to avoid"]'::jsonb,1,'Enjoyable activities are sustainable.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
